1	package websocket
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"strconv"
8		"sync"
9		"time"
10	
11		"github.com/gorilla/mux"
12	)
13	
14	const (
15		MaxLogBuffer  int = 1000
16		MaxSSEClients int = 100
17	)
18	
19	type LogEvent struct {
20		Type      EventType              `json:"type"`
21		Module    string                 `json:"module"` // "knirvchain", "knirvgateway", "knirvgraph"
22		Level     string                 `json:"level"`  // "info", "warn", "error", "debug"
23		Message   string                 `json:"message"`
24		Source    string                 `json:"source"`
25		Metadata  map[string]interface{} `json:"metadata,omitempty"`
26		Timestamp time.Time              `json:"timestamp"`
27	}
28	
29	type LogStreamHandler struct {
30		clients    map[string]map[chan LogEvent]bool
31		mu         sync.RWMutex
32		logBuffer  []LogEvent
33		bufferSize int
34	}
35	
36	var logStreamHandler *LogStreamHandler
37	
38	func GetLogStreamHandler() *LogStreamHandler {
39		if logStreamHandler == nil {
40			logStreamHandler = &LogStreamHandler{
41				clients:    make(map[string]map[chan LogEvent]bool),
42				logBuffer:  make([]LogEvent, 0, MaxLogBuffer),
43				bufferSize: MaxLogBuffer,
44			}
45		}
46		return logStreamHandler
47	}
48	
49	func (h *LogStreamHandler) RegisterRoutes(r *mux.Router) {
50		r.HandleFunc("/api/logs/stream", h.handleLogStream).Methods("GET")
51		r.HandleFunc("/api/logs/module/{module}", h.handleModuleLogStream).Methods("GET")
52		r.HandleFunc("/api/logs/history", h.handleLogHistory).Methods("GET")
53	}
54	
55	func (h *LogStreamHandler) handleLogStream(w http.ResponseWriter, r *http.Request) {
56		h.serveSSE(w, r, "")
57	}
58	
59	func (h *LogStreamHandler) handleModuleLogStream(w http.ResponseWriter, r *http.Request) {
60		vars := mux.Vars(r)
61		module := vars["module"]
62		h.serveSSE(w, r, module)
63	}
64	
65	func (h *LogStreamHandler) serveSSE(w http.ResponseWriter, r *http.Request, module string) {
66		w.Header().Set("Content-Type", "text/event-stream")
67		w.Header().Set("Cache-Control", "no-cache")
68		w.Header().Set("Connection", "keep-alive")
69		w.Header().Set("X-Accel-Buffering", "no")
70	
71		if module != "" {
72			w.Header().Set("X-Target-Module", module)
73		}
74	
